from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient


class TRSv2HttpClient(HttpClient):
    """ This class provides a client for the TRS v2 API. """
    def __init__(self, base_url, connection_alias):
        super(TRSv2HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/trs/v2"

    def config_ssh_tunnel(self, dist_name, operation, timeout=30):
        endpoint = '/ssh-tunnel'
        headers = {
            "accept": "application/json"
        }
        payload = {
            "operation": operation,
            "distName": dist_name
        }
        return self._send_post_request(endpoint=endpoint, headers=headers, json=payload, timeout=timeout)

    def delete_certificates_by_id(self, certificate_id, timeout=30):
        endpoint = f'/operator/certificates/{certificate_id}'
        headers = {
            "Content-Type": "application/json"
        }
        return self._send_delete_request(endpoint=endpoint, headers=headers, timeout=timeout)
